-- CASYCO · Filtro de compras · actualización 15-10-2026
-- 1) Compras puede editar OCs enviadas (sin autorizar ni pagar)
-- 2) Catálogo de proveedores importado de RELACION DE PROVEEDORES CYC (con RFC)
-- 3) OCs nuevas de la hoja D 15/10
-- Pegar completo en Supabase > SQL Editor > New query > Run

-- ---------- 1) Permisos de edición ----------
drop policy if exists "docs_insertar" on public.docs;
create policy "docs_insertar" on public.docs for insert to authenticated with check (
  public.mi_rol() in ('direccion', 'contabilidad')
  or (public.mi_rol() = 'compras' and (coleccion in ('ocs', 'proveedores', 'solicitantes') or (coleccion = 'config' and id = 'obras')))
);
drop policy if exists "docs_actualizar" on public.docs;
create policy "docs_actualizar" on public.docs for update to authenticated
using (
  public.mi_rol() in ('direccion', 'contabilidad')
  or (public.mi_rol() = 'compras' and (coleccion in ('ocs', 'proveedores', 'solicitantes') or (coleccion = 'config' and id = 'obras')))
)
with check (
  public.mi_rol() in ('direccion', 'contabilidad')
  or (public.mi_rol() = 'compras' and (coleccion in ('ocs', 'proveedores', 'solicitantes') or (coleccion = 'config' and id = 'obras')))
);

-- Compras puede corregir datos de la OC, pero no autorizar, pagar ni tocar OCs pagadas
create or replace function public.docs_guardia() returns trigger language plpgsql as $$
begin
  if new.coleccion = 'ocs' and public.mi_rol() = 'compras' then
    if coalesce(old.data->>'fechaPago', '') <> '' then
      raise exception 'La OC ya está pagada; no se puede editar.';
    end if;
    if coalesce(old.data->>'fechaPago', '') is distinct from coalesce(new.data->>'fechaPago', '')
       or coalesce(old.data->>'banco', '') is distinct from coalesce(new.data->>'banco', '')
       or coalesce(old.data->>'notaDir', '') is distinct from coalesce(new.data->>'notaDir', '') then
      raise exception 'Compras no puede registrar pagos ni notas de dirección.';
    end if;
    if coalesce(old.data->>'estatus', '') is distinct from coalesce(new.data->>'estatus', '')
       and not (new.data->>'estatus' = 'PENDIENTE' and coalesce(new.data->>'fechaAut', '') = '') then
      raise exception 'Compras no puede autorizar ni cambiar el estatus.';
    end if;
    if coalesce(new.data->>'fechaAut', '') <> '' and coalesce(old.data->>'fechaAut', '') is distinct from coalesce(new.data->>'fechaAut', '') then
      raise exception 'Compras no puede autorizar.';
    end if;
  end if;
  return new;
end $$;
drop trigger if exists docs_guardia on public.docs;
create trigger docs_guardia before update on public.docs for each row execute function public.docs_guardia();

-- ---------- 2) Proveedores (no reemplaza los que ya registraron en la app) ----------
on conflict (coleccion, id) do nothing;

-- ---------- 3) OCs nuevas de la hoja D 15/10 ----------
on conflict (coleccion, id) do nothing;

-- P01944 (CEMEX, SMA): en la hoja del 15/10 el monto bajó a $68,440.00 y la solicita JULIETA.
-- Sólo se aplica si en la app sigue con el monto anterior ($80,910.00) y no está pagada.
update public.docs
set data = data
  || jsonb_build_object('monto', 68440, 'solicita', 'JULIETA')
  || jsonb_build_object('editada', coalesce(data->'editada', '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
       'fecha', '2026-10-15', 'por', 'hoja Drive D 15/10', 'cambios', 'Monto $80,910.00 → $68,440.00; Solicita FERNANDA → JULIETA')))
  || case when data->>'estatus' = 'AUTORIZADO' then jsonb_build_object('estatus', 'PENDIENTE', 'fechaAut', '') else '{}'::jsonb end
where coleccion = 'ocs' and id = 'P01944' and (data->>'monto')::numeric = 80910 and coalesce(data->>'fechaPago', '') = '';
